gcW_(){return"\u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646: \u0627\u0632 \u0645\u0646\u0648\u06cc \u0641\u0631\u0648\u0634 > \u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0645\u0627\u0644\u06cc\u0627\u062a\u06cc \u0642\u0627\u0628\u0644 \u062f\u0633\u062a\u0631\u0633\u06cc \u0627\u0633\u062a."},
gcVX(){return"\u06a9\u0627\u0644\u0627 \u0648 \u062e\u062f\u0645\u0627\u062a: \u062f\u0631 \u0647\u0645\u06cc\u0646 \u0645\u0646\u0648 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u06a9\u062f \u0645\u0627\u0644\u06cc\u0627\u062a\u06cc \u0648 \u0648\u0627\u062d\u062f \u0631\u0627 \u0648\u06cc\u0631\u0627\u06cc\u0634 \u06cc\u0627 \u0627\u0632 \u0627\u06a9\u0633\u0644 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f."},
gcVY(){return"\u062f\u0631 \u0635\u0648\u0631\u062a \u0628\u0631\u0648\u0632 \u062e\u0637\u0627\u06cc \u0627\u062a\u0635\u0627\u0644\u060c \u0644\u0627\u06af \u06a9\u0627\u0645\u0644 \u062f\u0631 \u0645\u0627\u0698\u0648\u0644 \xab\u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646\xbb \u0648 \u0628\u062e\u0634 \u062a\u06cc\u06a9\u062a\u06cc\u0646\u06af \u062f\u0631 \u062f\u0633\u062a\u0631\u0633 \u0627\u0633\u062a."},
gbsV(){return"\u0634\u0646\u0627\u0633\u0647 \u062d\u0627\u0641\u0638\u0647 \u0645\u0627\u0644\u06cc\u0627\u062a\u06cc"},
gbsJ(){return"\u06a9\u062f \u0627\u0642\u062a\u0635\u0627\u062f\u06cc"},
gcXM(){return"\u062d\u0627\u0644\u062a \u0633\u0646\u062f\u0628\u0627\u06a9\u0633"},
gcXN(){return"\u0628\u0627 \u0641\u0639\u0627\u0644 \u0628\u0648\u062f\u0646 \u0627\u06cc\u0646 \u06af\u0632\u06cc\u0646\u0647\u060c \u062f\u0631\u062e\u0648\u0627\u0633\u062a\u200c\u0647\u0627 \u0628\u0647 \u0645\u062d\u06cc\u0637 \u0622\u0632\u0645\u0627\u06cc\u0634\u06cc \u0633\u0627\u0645\u0627\u0646\u0647 \u0627\u0631\u0633\u0627\u0644 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f."},
gcXA(){return"\u06a9\u0644\u06cc\u062f \u062e\u0635\u0648\u0635\u06cc (PEM)"},
